import { pipeline } from 'node:stream/promises'
import { createReadStream } from 'node:fs'
import { Transform, Writable } from 'node:stream'
import { parse } from 'csv-parse'

const BATCH = 1000

const batcher = new Transform({
  objectMode: true,
  transform(row, _enc, cb) {
    this.rows ??= []
    this.rows.push(row)
    if (this.rows.length >= BATCH) { const b = this.rows; this.rows = []; return cb(null, b) }
    cb()
  },
  flush(cb) { cb(null, this.rows?.length ? this.rows : undefined) },
})

const writer = new Writable({
  objectMode: true,
  async write(batch, _enc, cb) {
    try { await db.insertMany(batch); cb() } catch (err) { cb(err) }
  },
})

await pipeline(createReadStream('data.csv'), parse({ columns: true }), batcher, writer)

import { AsyncLocalStorage } from 'node:async_hooks'
import { randomUUID } from 'node:crypto'

const context = new AsyncLocalStorage()

app.use((req, res, next) => {
  const store = { requestId: req.headers['x-request-id'] ?? randomUUID() }
  context.run(store, next)
})

export function log(message) {
  const store = context.getStore()
  console.log(JSON.stringify({ requestId: store?.requestId, message }))
}

process.on('SIGTERM', async () => {
  isShuttingDown = true               // readiness probe now returns 503
  await sleep(5000)                   // let endpoints propagate
  server.close(() => process.exit(0))
  server.closeIdleConnections()
  setTimeout(() => {
    server.closeAllConnections()
    process.exit(1)
  }, 15000).unref()
})

process.on('unhandledRejection', (reason) => {
  logger.fatal({ err: reason }, 'unhandled rejection')
  throw reason                       // turn it into uncaughtException
})

process.on('uncaughtException', (err) => {
  logger.fatal({ err }, 'uncaught exception')
  gracefulShutdown()                 // stop taking traffic, then exit
  setTimeout(() => process.exit(1), 10000).unref()
})

